// Event-derived projections are loaded only when a history surface requests
// them. Keep this separate from current-state hydration.
import { eventFacts, eventCatalog, activityRange } from './facts.js';
import { readGameRoute } from './games.js';
import { readJackpotRoute } from './jackpots.js';
import { readPlayerRoute } from './player.js';
import { readViewerRoute, playerDay } from './viewer.js';
import { readBoardRoute } from './boards.js';
import { readCrapsResults } from './craps-results.js';
import { readReplayRoute } from './replay.js';
import { readFeedRoute } from './feeds.js';
import { playerAddress, uint, playerState } from './state.js';
import { ChainDataError } from './client.js';

export async function readHistoryRoute(s, url, { signal } = {}) {
  const p = url.pathname.split('/').filter(Boolean); const q = url.searchParams;
  const craps = await readCrapsResults(s, url, { signal }); if (craps !== undefined) return craps;
  const replay = await readReplayRoute(s, url, { signal }); if (replay !== undefined) return replay;
  const playerRoute = await readPlayerRoute(s, url, { signal }); if (playerRoute !== undefined) return playerRoute;
  const viewer = await readViewerRoute(s, url, { signal }); if (viewer !== undefined) return viewer;
  const board = await readBoardRoute(s, url, { signal }); if (board !== undefined) return board;
  const feed = await readFeedRoute(s, url, { signal }); if (feed !== undefined) return feed;
  const game = await readGameRoute(s, url, { signal }); if (game !== undefined) return game;
  const jackpot = await readJackpotRoute(s, url, { signal }); if (jackpot !== undefined) return jackpot;
  if (p[0] === 'player' && p.length === 2 && q.has('day')) {
    const day = uint(q.get('day')); const range = await activityRange(s, day, signal);
    if (range.fromBlock > range.toBlock) throw new ChainDataError('This game day has not started.', 'DAY_NOT_STARTED');
    const player = playerAddress(p[1]);
    const view = await playerDay(s, player, day, signal);
    return { player, day, blockNumber: String(range.toBlock), historicalUnavailable: false,
      scoreBreakdown: null, dailyActivity: view.activity, quests: view.activity.quests,
      claimableEth: null, flipBalance: null, dgnrsBalance: null, sdgnrsBalance: null, wwxrpBalance: null,
      totalClaimed: null, totalCredited: null, tickets: null, currentStreak: null, shields: null,
      historicalBalancesAvailable: false };
  }
  if (p[0] === 'player' && ['facts', 'sdgnrs-redemptions', 'wwxrp-draws'].includes(p[2])) {
    const player = playerAddress(p[1]);
    const names = p[2] === 'facts' ? (q.get('names') ?? '').split(',').filter(Boolean)
      : p[2] === 'sdgnrs-redemptions' ? ['RedemptionSubmitted', 'RedemptionClaimed'] : ['DrawEntered', 'DrawClaimed', 'IncineratorEntered', 'IncineratorResolved'];
    if (!names.length) throw new ChainDataError('Choose event names.', 'INVALID_REQUEST');
    const events = await eventFacts(s, names, { player, fromBlock: q.has('since') ? uint(q.get('since'), Number.MAX_SAFE_INTEGER) + 1 : undefined, signal });
    return { toBlock: s.block.number, events, truncated: false };
  }
  if (url.pathname === '/game/craps/events') {
    const days = 2; const current = s.client.dayAt(s.block.timestamp);
    const window = await activityRange(s, Math.max(1, current - days), signal);
    const fromBlock = Math.max(window.fromBlock, q.has('since') ? uint(q.get('since'), Number.MAX_SAFE_INTEGER) + 1 : 0);
    const names = (await eventCatalog()).filter(row => row.contract === 'CRAPS').map(row => row.event.name);
    const events = await eventFacts(s, names, { contract: 'CRAPS', fromBlock, signal });
    return { fromBlock, toBlock: s.block.number, lookbackBlocks: s.block.number - window.fromBlock + 1, events };
  }
  if (url.pathname === '/game/facts/sum') {
    if (q.get('name') !== 'YieldSurplusDistributed' || q.get('arg') !== 'perRecipientShare') throw new ChainDataError('Unknown sum.', 'INVALID_REQUEST');
    const events = await eventFacts(s, ['YieldSurplusDistributed'], { contract: 'GAME', signal });
    return { toBlock: s.block.number, count: events.length, sum: String(events.reduce((sum, row) => sum + BigInt(row.args.perRecipientShare), 0n)) };
  }
  return undefined;
}
